@block GroundPlanar begin
    @ports p::Power{Planar}, [frame = "world"]
    @equations begin
        p.f[1] ~ 0.0
        p.f[2] ~ 0.0
        p.f[3] ~ 0.0
    end
    @causality p => (:flow_out, :fixed)
end

@block BodyPlanar begin
    @ports p::Power{Planar}, [frame = "arm"]
    @parameters begin
        m::Real = 1.2, [unit = "kg", min = 0, description = "Mass"]
        J::Real = 0.04, [unit = "kg*m^2", min = 0, description = "Yaw inertia about the CoM"]
    end
    @variables P::Vec{3} = [0.0, 0.0, 0.0], [state = :prefer, description = "Momentum [angular; linear]"]
    @equations begin
        # Diagonal CoM inertia (D-MB3), written component-wise so each unit is checked (D-MB10).
        p.f[1] ~ P[1] / J
        p.f[2] ~ P[2] / m
        p.f[3] ~ P[3] / m
        for k in 1:3
            ddt(P[k]) ~ p.e[k]
        end
    end
    @causality p => :flow_out
end
